const setItemNotes = `-- name: SetItemNotes :exec
UPDATE item SET
  notes = ?,
  updated_at = NOW(3)
WHERE id = ?
AND account_id = ?
AND deleted_at IS NULL
`

type SetItemNotesParams struct {
	Notes     sql.NullString
	ID        string
	AccountID string
}

func (q *Queries) SetItemNotes(ctx context.Context, arg SetItemNotesParams) error {
	_, err := q.db.ExecContext(ctx, setItemNotes, arg.Notes, arg.ID, arg.AccountID)
	return err
}

const updateItem = `-- name: UpdateItem :exec
UPDATE item SET
  sku = COALESCE(?, sku),
  description = COALESCE(?, description),
  notes = COALESCE(?, notes),
  updated_at = NOW(3)
WHERE id = ?
AND account_id = ?
AND deleted_at IS NULL
`

type UpdateItemParams struct {
	Sku         sql.NullString
	Description sql.NullString
	Notes       sql.NullString
	ID          string
	AccountID   string
}

func (q *Queries) UpdateItem(ctx context.Context, arg UpdateItemParams) error {
	_, err := q.db.ExecContext(ctx, updateItem,
		arg.Sku,
		arg.Description,
		arg.Notes,
		arg.ID,
		arg.AccountID,
	)
	return err
}

const updateItemConsumptionQuantityUnits = `-- name: UpdateItemConsumptionQuantityUnits :exec
UPDATE quantity q
JOIN consumption c ON (c.quantity_id = q.id OR c.waste_quantity_id = q.id)
JOIN item i ON i.id = c.item_id
SET q.unit_id = ?
WHERE i.id = ?
AND i.account_id = ?
AND i.deleted_at IS NULL
`

type UpdateItemConsumptionQuantityUnitsParams struct {
	NewUnitID string
	ItemID    string
	AccountID string
}

func (q *Queries) UpdateItemConsumptionQuantityUnits(ctx context.Context, arg UpdateItemConsumptionQuantityUnitsParams) error {
	_, err := q.db.ExecContext(ctx, updateItemConsumptionQuantityUnits, arg.NewUnitID, arg.ItemID, arg.AccountID)
	return err
}

