const updateItemUnitCostRate = `-- name: UpdateItemUnitCostRate :exec
UPDATE rate r
SET r.value = ?,
    r.denominator_unit_id = ?
WHERE r.id = (
    SELECT i.unit_cost_id FROM item i
    WHERE i.id = ?
    AND i.account_id = ?
    AND i.deleted_at IS NULL
)
`

type UpdateItemUnitCostRateParams struct {
	Value             string
	DenominatorUnitID string
	ItemID            string
	AccountID         string
}

// Updates an item's unit cost rate value and denominator unit.
func (q *Queries) UpdateItemUnitCostRate(ctx context.Context, arg UpdateItemUnitCostRateParams) error {
	_, err := q.db.ExecContext(ctx, updateItemUnitCostRate,
		arg.Value,
		arg.DenominatorUnitID,
		arg.ItemID,
		arg.AccountID,
	)
	return err
}

const updateMaterialOrderPointUnit = `-- name: UpdateMaterialOrderPointUnit :exec
UPDATE quantity q
JOIN material m ON m.order_point_id = q.id
JOIN item i ON i.id = m.item_id
SET q.unit_id = ?
WHERE i.id = ?
AND i.account_id = ?
AND i.deleted_at IS NULL
AND i.item_type_code = 'material'
`

type UpdateMaterialOrderPointUnitParams struct {
	NewUnitID string
	ItemID    string
	AccountID string
}

func (q *Queries) UpdateMaterialOrderPointUnit(ctx context.Context, arg UpdateMaterialOrderPointUnitParams) error {
	_, err := q.db.ExecContext(ctx, updateMaterialOrderPointUnit, arg.NewUnitID, arg.ItemID, arg.AccountID)
	return err
}
